<?php
namespace App\Http\Controllers\Configuration;
use App\Http\Controllers\Controller; use App\Models\{Menu,Permission,Role,RoleMenuPermission}; use App\Services\Audit\ActivityLogService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class MenuSecurityController extends Controller { public function __construct(){ $this->middleware('menu.permission:config.menu-security,view')->only(['index','edit']);$this->middleware('menu.permission:config.menu-security,edit')->only('update'); }
 public function index(){return view('configuration.menu-security.index',['roles'=>Role::orderBy('code')->get()]);} public function edit(Role $role){$menus=Menu::where('is_active',true)->orderBy('sort_order')->orderBy('label')->get();$permissions=Permission::orderBy('id')->get();$grants=RoleMenuPermission::where('role_id',$role->id)->get()->mapWithKeys(fn($g)=>[$g->menu_id.':'.$g->permission_id=>true]);return view('configuration.menu-security.edit',compact('role','menus','permissions','grants'));}
 public function update(Request $r,Role $role,ActivityLogService $audit){$data=$r->validate(['grants'=>['nullable','array'],'grants.*'=>['string']]);$before=RoleMenuPermission::where('role_id',$role->id)->get()->toArray();$pairs=[];foreach($data['grants']??[] as $value){[$menuId,$permissionId]=array_map('intval',explode(':',$value,2));if(Menu::whereKey($menuId)->exists()&&Permission::whereKey($permissionId)->exists())$pairs[]=['role_id'=>$role->id,'menu_id'=>$menuId,'permission_id'=>$permissionId];}DB::transaction(function() use($role,$pairs){RoleMenuPermission::where('role_id',$role->id)->delete();if($pairs)RoleMenuPermission::insert($pairs);});$after=RoleMenuPermission::where('role_id',$role->id)->get()->toArray();$audit->record('config.menu-security','update',$role,$before,$after);return redirect()->route('config.menu-security.edit',$role)->with('success','Menu permissions updated.');}
}
